import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()

    # Normalize text columns
    for col in ['Order_ID', 'Product', 'Category', 'Region']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    # Remove exact duplicate rows / enforce unique Order_ID
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    else:
        df = df.drop_duplicates()

    # Quantity
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')

    # Price: remove currency symbols/commas and convert to numeric
    if 'Price' in df.columns:
        df['Price'] = (
            df['Price'].astype('string')
            .str.replace(r'[\$,]', '', regex=True)
            .str.strip()
        )
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')

    # Revenue: numeric and recompute from Quantity * Price where possible
    if 'Revenue' in df.columns:
        df['Revenue'] = pd.to_numeric(df['Revenue'], errors='coerce')
        if 'Quantity' in df.columns and 'Price' in df.columns:
            calc = df['Quantity'] * df['Price']
            df['Revenue'] = calc.where(calc.notna(), df['Revenue'])

    # Date: parse to datetime, invalid values become NaT
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')

    # Category label variants are fixed by stripping whitespace above
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Region', 'Quantity'])
    totals = d.groupby('Region', dropna=True)['Quantity'].sum()
    return {str(region): int(total) for region, total in totals.items()}
